def fast_pow(x, n):
    # Exponentiation by squaring: x^13 with 13 = 0b1101 needs only
    # x, x^2, x^4, x^8 and multiplies the ones whose bit is set.
    if n < 0:
        x, n = 1.0 / x, -n       # negative exponent -> invert the base
    result = 1.0
    while n:
        if n & 1:                # lowest remaining bit is set
            result *= x          # ... so this power of x contributes
        x *= x                   # climb: x -> x^2 -> x^4 -> x^8 ...
        n >>= 1                  # move to the next bit of the exponent
    return result                # O(log n) multiplications


def merge_intervals(intervals):
    # Sort by start; then any mergeable neighbor is ADJACENT — one pass.
    intervals.sort(key=lambda iv: iv[0])      # O(N log N) dominates
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            # Overlaps the interval we are building -> extend its right edge.
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])       # gap -> start a new interval
    return merged

