# A Python-list-like dynamic array built on a fixed-capacity backing block.
# This mirrors what CPython's list really does: keep a block BIGGER than
# needed and grow it geometrically, so append is amortized O(1).

class DynamicArray:
    def __init__(self):
        self._n = 0                    # how many real elements are stored
        self._capacity = 1             # size of the underlying block
        self._store = [None]           # the fixed-size backing block

    def __len__(self):
        return self._n                 # O(1): we track the count ourselves

    def _index(self, i):
        # Normalize negative indices and reject out-of-range ones,
        # exactly like the built-in list does.
        if i < 0:
            i += self._n               # a[-1] means a[n-1]
        if not 0 <= i < self._n:
            raise IndexError('index out of range')
        return i

    def __getitem__(self, i):
        return self._store[self._index(i)]    # O(1) random access

    def __setitem__(self, i, value):
        self._store[self._index(i)] = value   # O(1) overwrite in place

    def _resize(self, new_capacity):
        # O(N) copy into a fresh, larger block. Because capacity DOUBLES,
        # a resize happens only after N cheap appends -> amortized O(1).
        new_store = [None] * new_capacity
        for k in range(self._n):
            new_store[k] = self._store[k]     # copy every live element
        self._store = new_store
        self._capacity = new_capacity

    def append(self, value):
        # Amortized O(1): usually drops into a spare slot.
        if self._n == self._capacity:
            self._resize(2 * self._capacity)  # full -> double the block
        self._store[self._n] = value
        self._n += 1

    def insert(self, i, value):
        # O(N - i): every element from i onward shifts one slot right.
        if self._n == self._capacity:
            self._resize(2 * self._capacity)
        i = max(0, min(i, self._n))           # clamp like list.insert does
        for k in range(self._n, i, -1):
            self._store[k] = self._store[k - 1]   # shift the tail rightwards
        self._store[i] = value
        self._n += 1

    def pop(self, i=-1):
        # O(1) for the last slot, O(N - i) anywhere else (left-shift the tail).
        i = self._index(i)
        value = self._store[i]
        for k in range(i, self._n - 1):
            self._store[k] = self._store[k + 1]   # close the gap
        self._store[self._n - 1] = None           # drop the stale reference
        self._n -= 1
        return value


if __name__ == '__main__':
    a = DynamicArray()
    for v in [10, 20, 30, 40]:
        a.append(v)                    # grows: capacity 1 -> 2 -> 4
    a.insert(1, 15)                    # [10, 15, 20, 30, 40]
    assert [a[i] for i in range(len(a))] == [10, 15, 20, 30, 40]
    assert a.pop(0) == 10              # O(N) front pop, like list.pop(0)
    assert a[-1] == 40                 # negative indexing works
    print('DynamicArray OK, size', len(a))

