def first_true(lo, hi, ok):
    # Generic boundary search over integers lo..hi where ok() reads
    # F F F T T T. Returns the smallest value with ok(v) True,
    # or hi + 1 if ok is never True on the range.
    hi += 1                          # sentinel slot: 'no True anywhere' answer
    while lo < hi:                   # window [lo, hi) still has candidates
        mid = (lo + hi) // 2         # rounds DOWN, so mid < hi always
        if ok(mid):
            hi = mid                 # mid might BE the boundary: keep it
        else:
            lo = mid + 1             # boundary is strictly right of mid
    return lo                        # lo == hi == the F->T boundary


def lower_bound(a, x):
    # First index i with a[i] >= x — bisect_left rebuilt on the template.
    return first_true(0, len(a) - 1, lambda i: a[i] >= x)


def upper_bound(a, x):
    # First index i with a[i] > x — the ONLY change is >= becoming >.
    return first_true(0, len(a) - 1, lambda i: a[i] > x)


assert lower_bound([10, 20, 20, 30], 20) == 1   # first 20
assert upper_bound([10, 20, 20, 30], 20) == 3   # just past the last 20
assert lower_bound([10, 20], 99) == 2           # sentinel: len(a) means 'absent'

def search_rotated(a, target):
    # KEY FACT: at every mid, at least one half is fully sorted.
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid                    # found it
        if a[lo] <= a[mid]:               # left half [lo..mid] is sorted
            if a[lo] <= target < a[mid]:
                hi = mid - 1              # target provably inside the sorted half
            else:
                lo = mid + 1              # ... provably NOT there -> other half
        else:                             # right half [mid..hi] is sorted
            if a[mid] < target <= a[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1                             # window emptied: absent


def single_non_duplicate(a):
    # Pairs start at even indices BEFORE the single element, odd AFTER.
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        mid -= mid % 2                    # snap mid down to a pair-start (even) index
        if a[mid] == a[mid + 1]:
            lo = mid + 2                  # pairing intact here -> single is rightward
        else:
            hi = mid                      # pairing broken -> single at mid or leftward
    return a[lo]                          # window closed on the single element

