# The four searches you must be able to write cold, from scratch.
# Two window conventions are shown deliberately:
#   - exact search uses an INCLUSIVE window [lo, hi]  with  while lo <= hi
#   - boundary searches use a HALF-OPEN window [lo, hi) with while lo < hi

def binary_search(a, x):
    # Exact-match search on a sorted list. Returns an index of x, or -1.
    lo, hi = 0, len(a) - 1          # inclusive window that may contain x
    while lo <= hi:                 # window non-empty
        mid = (lo + hi) // 2        # Python ints cannot overflow here
        if a[mid] == x:
            return mid              # hit (any one occurrence)
        if a[mid] < x:
            lo = mid + 1            # discard left half INCLUDING mid
        else:
            hi = mid - 1            # discard right half INCLUDING mid
    return -1                       # window emptied -> absent


def lower_bound(a, x):
    # First index i with a[i] >= x; returns len(a) if none. == bisect_left.
    lo, hi = 0, len(a)              # half-open [lo, hi): answer lives here
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] >= x:
            hi = mid                # mid could BE the answer -> keep it in range
        else:
            lo = mid + 1            # mid too small -> answer strictly right
    return lo                       # lo == hi == the boundary


def upper_bound(a, x):
    # First index i with a[i] > x. The ONLY change from lower_bound: > not >=.
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] > x:              # strict comparison skips equal elements
            hi = mid
        else:
            lo = mid + 1
    return lo


def first_true(lo, hi, ok):
    # Generic boundary search: ok over lo..hi reads F..F T..T.
    # Returns the smallest v with ok(v), or hi + 1 if ok is never True.
    hi += 1                         # sentinel: the 'all False' answer
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid                # boundary at mid or left of it
        else:
            lo = mid + 1            # boundary strictly right of mid
    return lo


if __name__ == '__main__':
    a = [10, 20, 20, 20, 30]
    assert binary_search(a, 30) == 4
    assert binary_search(a, 25) == -1        # absent value
    assert lower_bound(a, 20) == 1           # first 20
    assert upper_bound(a, 20) == 4           # one past the last 20
    assert upper_bound(a, 20) - lower_bound(a, 20) == 3   # count of 20s
    assert first_true(0, 10, lambda v: v * v >= 17) == 5  # ceil(sqrt(17))
    print('toolkit OK')

