def is_same(p, q):
    # Truth table over Nones, in the right order:
    if p is None and q is None:
        return True                      # two empty trees match
    if p is None or q is None:
        return False                     # one empty, one not: shape differs
    return (p.val == q.val               # roots agree ...
            and is_same(p.left, q.left)      # ... left sides agree ...
            and is_same(p.right, q.right))   # ... right sides agree

def is_symmetric(root):
    # A tree is symmetric iff left subtree mirrors right subtree.
    def mirror(a, b):
        if a is None and b is None:
            return True
        if a is None or b is None:
            return False
        return (a.val == b.val
                and mirror(a.left, b.right)   # outer children pair up
                and mirror(a.right, b.left))  # inner children pair up
    return root is None or mirror(root.left, root.right)

def root_to_node_path(root, target):
    path = []
    def dfs(node):
        if node is None:
            return False
        path.append(node.val)          # tentatively part of the path
        if node.val == target:
            return True                # found: freeze everything below
        if dfs(node.left) or dfs(node.right):
            return True                # target is deeper: keep this node
        path.pop()                     # BACKTRACK: this node is a dead end
        return False
    dfs(root)
    return path                        # [] if the target is absent

def lca(root, p, q):
    # p and q are node OBJECTS guaranteed to be in the tree.
    if root is None or root is p or root is q:
        return root                    # bottom, or found one target
    left = lca(root.left, p, q)        # what did the left side find?
    right = lca(root.right, p, q)      # and the right side?
    if left and right:                 # one target on each side:
        return root                    # this node is the split point
    return left if left else right     # both on one side (or neither)

def serialize(root):
    # Preorder dump; '#' marks every None -> shape is fully captured.
    parts = []
    def dfs(node):
        if node is None:
            parts.append('#')        # the null marker removes all ambiguity
            return
        parts.append(str(node.val))  # Root ...
        dfs(node.left)               # ... then the whole left subtree
        dfs(node.right)              # ... then the whole right subtree
    dfs(root)
    return ','.join(parts)           # join once: O(N) total, not O(N^2)

def deserialize(data):
    tokens = iter(data.split(','))   # a stream consumed left to right
    def build():
        tok = next(tokens)
        if tok == '#':
            return None              # a hole exactly where one was written
        node = TreeNode(int(tok))
        node.left = build()          # preorder: rebuild left before right
        node.right = build()         # stream position stays synchronized
        return node
    return build()

def morris_inorder(root):
    out, cur = [], root
    while cur:
        if cur.left is None:
            out.append(cur.val)          # no left side: visit, go right
            cur = cur.right
        else:
            pred = cur.left              # find the inorder predecessor:
            while pred.right and pred.right is not cur:
                pred = pred.right        # rightmost node of left subtree
            if pred.right is None:
                pred.right = cur         # FIRST touch: lay the thread
                cur = cur.left           # and dive into the left subtree
            else:
                pred.right = None        # SECOND touch: heal the tree
                out.append(cur.val)      # left side done -> visit cur
                cur = cur.right
    return out

def morris_preorder(root):
    out, cur = [], root
    while cur:
        if cur.left is None:
            out.append(cur.val)          # leaf-ish node: visit, go right
            cur = cur.right
        else:
            pred = cur.left
            while pred.right and pred.right is not cur:
                pred = pred.right
            if pred.right is None:
                out.append(cur.val)      # preorder: visit BEFORE going left
                pred.right = cur         # thread as usual
                cur = cur.left
            else:
                pred.right = None        # thread already used: only clean up
                cur = cur.right
    return out

def search_bst(root, target):
    # INVARIANT: target, if present, lives in the subtree at `node`.
    node = root
    while node:                      # O(H): one node per level
        if node.val == target:
            return node              # found it
        elif target < node.val:
            node = node.left         # right subtree all > target: prune
        else:
            node = node.right        # left subtree all < target: prune
    return None                      # fell off the tree: absent


def ceil_bst(root, target):
    # Smallest value >= target. Record a candidate, then try to beat it.
    ans = -1                         # sentinel: no ceil found yet
    node = root
    while node:
        if node.val == target:
            return node.val          # exact hit is the tightest ceil
        if node.val > target:
            ans = node.val           # node works -- but look for tighter
            node = node.left         # smaller values that still >= target
        else:
            node = node.right        # node too small: ceil must be right
    return ans


def lca_bst(root, p, q):
    # First node whose value lies BETWEEN p and q = where paths split.
    lo, hi = min(p, q), max(p, q)    # normalize the order once
    node = root
    while node:
        if node.val < lo:
            node = node.right        # both targets larger: go right
        elif node.val > hi:
            node = node.left         # both targets smaller: go left
        else:
            return node              # lo <= val <= hi: this is the LCA
    return None

def is_valid_bst(root):
    # Each node must fit the OPEN window (low, high) set by ancestors.
    def check(node, low, high):
        if not node:
            return True                     # empty subtree: nothing to break
        if not (low < node.val < high):
            return False                    # violates an ancestor's bound
        return (check(node.left, low, node.val) and    # left: cap high
                check(node.right, node.val, high))     # right: raise low
    return check(root, float('-inf'), float('inf'))


def bst_from_preorder(preorder):
    # preorder[0] is the root; afterwards each call consumes the next
    # value ONLY if it fits its window. One shared cursor -> each index
    # is visited once -> O(N) total (vs O(N*H) repeated inserts).
    i = 0                                    # shared cursor into preorder

    def build(low, high):
        nonlocal i
        if i == len(preorder) or not (low < preorder[i] < high):
            return None                      # value belongs to an ancestor
        node = TreeNode(preorder[i])         # claim this value
        i += 1                               # advance the shared cursor
        node.left = build(low, node.val)     # smaller values come first
        node.right = build(node.val, high)   # then the larger ones
        return node

    return build(float('-inf'), float('inf'))

def delete_node(root, key):
    # Recursive delete. NOTE the re-link pattern: the parent assigns
    # the returned subtree root back into its own child slot.
    if root is None:
        return None                    # key not present: nothing to do
    if key < root.val:
        root.left = delete_node(root.left, key)     # re-link left
    elif key > root.val:
        root.right = delete_node(root.right, key)   # re-link right
    else:
        # Found the node. Three cases by number of children:
        if root.left is None:
            return root.right          # 0 children or right-only: splice
        if root.right is None:
            return root.left           # left-only child: splice it up
        # Two children: overwrite with the inorder SUCCESSOR
        # (leftmost node of the right subtree), then delete that.
        succ = root.right
        while succ.left:               # walk to min of right subtree
            succ = succ.left
        root.val = succ.val            # copy successor's key up here
        root.right = delete_node(root.right, succ.val)  # remove the dup
    return root                        # hand (possibly new) root back up


def inorder_successor(root, p):
    # Successor = smallest value > p.val: candidate-tracking descent.
    ans = None
    node = root
    while node:
        if node.val > p.val:
            ans = node                 # works -- try to find a tighter one
            node = node.left
        else:
            node = node.right          # too small: successor is right
    return ans                         # None means p was the maximum

