class TreeNode:
    # One BST node: a key plus two child references.
    def __init__(self, val):
        self.val = val                # the key stored here
        self.left = None              # subtree of strictly smaller keys
        self.right = None             # subtree of strictly larger keys


class BST:
    # From-scratch Binary Search Tree.
    # Every descent operation is O(H): H ~ log2(N) when balanced,
    # H = N when keys arrive pre-sorted (degenerate chain).

    def __init__(self):
        self.root = None              # empty tree to start

    # ---------------- insert : O(H) time, O(1) space ----------------
    def insert(self, val):
        new = TreeNode(val)
        if self.root is None:
            self.root = new           # first key becomes the root
            return
        node = self.root
        while True:
            if val == node.val:
                return                # duplicate: strict BST ignores it
            if val < node.val:        # belongs somewhere on the left
                if node.left is None:
                    node.left = new   # found the empty slot: attach
                    return
                node = node.left      # keep descending left
            else:                     # belongs somewhere on the right
                if node.right is None:
                    node.right = new
                    return
                node = node.right     # keep descending right

    # ---------------- search : O(H) ----------------
    def search(self, val):
        node = self.root
        while node and node.val != val:
            # one comparison throws away an entire subtree
            node = node.left if val < node.val else node.right
        return node                   # the node, or None if absent

    # ---------------- min / max : O(H) ----------------
    def min_value(self):
        node = self.root
        while node and node.left:     # smallest key = leftmost node
            node = node.left
        return node.val if node else None

    def max_value(self):
        node = self.root
        while node and node.right:    # largest key = rightmost node
            node = node.right
        return node.val if node else None

    # ---------------- ceil / floor : O(H) ----------------
    def ceil(self, x):
        # smallest key >= x, or None if every key is smaller
        ans = None
        node = self.root
        while node:
            if node.val == x:
                return x              # exact match: tightest possible
            if node.val > x:
                ans = node.val        # candidate; look left for tighter
                node = node.left
            else:
                node = node.right     # too small; ceil must be right
        return ans

    def floor(self, x):
        # largest key <= x, or None  (mirror image of ceil)
        ans = None
        node = self.root
        while node:
            if node.val == x:
                return x              # exact match wins immediately
            if node.val < x:
                ans = node.val        # candidate; look right for tighter
                node = node.right
            else:
                node = node.left      # too big; floor must be left
        return ans

    # ---------------- inorder successor : O(H) ----------------
    def successor(self, x):
        # smallest key strictly greater than x, or None
        ans = None
        node = self.root
        while node:
            if node.val > x:
                ans = node.val        # works; try to find a smaller one
                node = node.left
            else:
                node = node.right     # too small; go right
        return ans

    # ---------------- delete : O(H) ----------------
    def delete(self, val):
        # Public wrapper: the recursive helper returns each new subtree
        # root and the caller RE-LINKS it (the crucial Python pattern).
        self.root = self._delete(self.root, val)

    def _delete(self, node, val):
        if node is None:
            return None               # key was not in the tree
        if val < node.val:
            node.left = self._delete(node.left, val)    # re-link left
        elif val > node.val:
            node.right = self._delete(node.right, val)  # re-link right
        else:
            # Found it. Cases 1 & 2: at most one child -> splice it up.
            if node.left is None:
                return node.right     # covers the leaf case too (None)
            if node.right is None:
                return node.left
            # Case 3: two children. Copy the inorder successor's value
            # (leftmost of the right subtree), then delete that node --
            # it has no left child, so the sub-delete is case 1 or 2.
            succ = node.right
            while succ.left:
                succ = succ.left      # walk to min of right subtree
            node.val = succ.val       # overwrite with successor key
            node.right = self._delete(node.right, succ.val)
        return node                   # hand the (possibly new) root up

    # ------------- inorder : O(N), yields keys in sorted order -------------
    def inorder(self):
        out, stack, node = [], [], self.root
        while stack or node:
            while node:               # push the entire left spine
                stack.append(node)
                node = node.left
            node = stack.pop()        # next smallest key
            out.append(node.val)
            node = node.right         # then explore its right subtree
        return out


if __name__ == "__main__":
    t = BST()
    for v in [8, 3, 10, 1, 6, 14, 4, 7, 13]:
        t.insert(v)                   # build the classic example tree
    assert t.inorder() == [1, 3, 4, 6, 7, 8, 10, 13, 14]  # sorted!
    assert t.search(6) is not None and t.search(5) is None
    assert t.ceil(5) == 6 and t.floor(5) == 4
    assert t.successor(8) == 10       # next value after the root
    t.delete(8)                       # hardest case: two-child root
    assert t.inorder() == [1, 3, 4, 6, 7, 10, 13, 14]
    print("BST OK")

class TreeNode:
    # Minimal node so this file runs standalone.
    def __init__(self, val, left=None, right=None):
        self.val = val                # the key
        self.left = left              # smaller keys
        self.right = right            # larger keys


class BSTIterator:
    # Ascending iterator ('BST Iterator' sheet question).
    # Stack holds the CURRENT LEFT SPINE of the unvisited part; the
    # top is always the next-smallest node. Each node is pushed once
    # and popped once -> next() is amortized O(1). Space O(H).

    def __init__(self, root):
        self.stack = []
        self._push_left(root)         # prime with the root's spine

    def _push_left(self, node):
        while node:
            self.stack.append(node)   # remember every node passed
            node = node.left          # slide down-left

    def has_next(self):
        return bool(self.stack)       # empty spine = iteration done

    def next(self):
        node = self.stack.pop()       # next smallest, by construction
        self._push_left(node.right)   # successors live down-right
        return node.val


class BSTReverseIterator:
    # Mirror image: RIGHT spines give DESCENDING order.
    def __init__(self, root):
        self.stack = []
        self._push_right(root)

    def _push_right(self, node):
        while node:
            self.stack.append(node)   # stack the right spine
            node = node.right

    def has_next(self):
        return bool(self.stack)

    def next(self):
        node = self.stack.pop()       # next LARGEST value
        self._push_right(node.left)   # then its left subtree
        return node.val


def two_sum_bst(root, k):
    # 'Two Sum in BST' in O(N) time, O(H) space: the two iterators act
    # as the two ends of a sorted-array two-pointer scan.
    if root is None:
        return False
    lo, hi = BSTIterator(root), BSTReverseIterator(root)
    a, b = lo.next(), hi.next()       # smallest and largest keys
    while a < b:                      # pointers have not crossed
        if a + b == k:
            return True               # found the pair
        if a + b < k:
            a = lo.next()             # need a larger sum: move up
        else:
            b = hi.next()             # need a smaller sum: move down
    return False


if __name__ == "__main__":
    #        8
    #      /   \
    #     3     10        inorder: 1 3 6 8 10 14
    #    / \      \
    #   1   6     14
    root = TreeNode(8,
                    TreeNode(3, TreeNode(1), TreeNode(6)),
                    TreeNode(10, None, TreeNode(14)))
    it = BSTIterator(root)
    seen = []
    while it.has_next():
        seen.append(it.next())        # drain the iterator
    assert seen == [1, 3, 6, 8, 10, 14]
    assert two_sum_bst(root, 9) is True    # 3 + 6
    assert two_sum_bst(root, 27) is False  # no pair sums to 27
    print("Iterator OK")

