class TrieNode:
    __slots__ = ("children", "end")     # slots keep millions of nodes small
    def __init__(self):
        self.children = {}              # char -> TrieNode
        self.end = False                # does a stored word end here?


class Trie:
    # Sheet question: 'Implement Trie'. Every op is O(L) for a
    # word/prefix of length L -- independent of words stored.

    def __init__(self):
        self.root = TrieNode()          # root = the empty prefix ""

    def insert(self, word):
        node = self.root
        for ch in word:                 # one step per character
            if ch not in node.children:
                node.children[ch] = TrieNode()   # lazily build the path
            node = node.children[ch]
        node.end = True                 # mark the complete word

    def _walk(self, s):
        # Shared descent: node spelling `s`, or None if the path breaks.
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None             # prefix not present at all
        return node

    def search(self, word):
        node = self._walk(word)
        # path must exist AND carry the end flag -- corridor != word
        return node is not None and node.end

    def startsWith(self, prefix):
        return self._walk(prefix) is not None   # reaching it is enough

