class Node:
    # Trie node with COUNTERS instead of a boolean flag. Counters give
    # countWordsEqualTo / countWordsStartingWith / erase in O(L) with
    # zero restructuring (a path with pass_count 0 counts as absent).
    __slots__ = ("children", "end_count", "pass_count")

    def __init__(self):
        self.children = {}        # char -> Node
        self.end_count = 0        # how many stored words END exactly here
        self.pass_count = 0       # how many stored words PASS THROUGH here


class CountingTrie:
    # Striver 'Implement Trie II' interface. Every method is O(L).

    def __init__(self):
        self.root = Node()        # root = the empty prefix

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Node()   # create the missing edge
            node = node.children[ch]
            node.pass_count += 1             # one more word uses this path
        node.end_count += 1                  # this word terminates here

    def _walk(self, s):
        # Follow the path spelling s. Return None when the path breaks
        # OR has been fully erased (pass_count 0 = logically deleted).
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None or node.pass_count == 0:
                return None
        return node

    def count_words_equal_to(self, word):
        node = self._walk(word)
        return node.end_count if node else 0    # exact multiplicity

    def count_words_starting_with(self, prefix):
        node = self._walk(prefix)
        return node.pass_count if node else 0   # words through this node

    def search(self, word):
        return self.count_words_equal_to(word) > 0     # membership

    def starts_with(self, prefix):
        return self.count_words_starting_with(prefix) > 0

    def erase(self, word):
        # Remove ONE copy of word. Caller should verify presence first
        # (search), otherwise the counters would go negative.
        if not self.search(word):
            return False                     # nothing to erase
        node = self.root
        for ch in word:
            node = node.children[ch]
            node.pass_count -= 1             # one fewer word this way
        node.end_count -= 1                  # one fewer ending here
        return True


if __name__ == "__main__":
    t = CountingTrie()
    for w in ["apple", "apple", "app"]:
        t.insert(w)                          # 'apple' inserted twice
    assert t.count_words_equal_to("apple") == 2
    assert t.count_words_starting_with("app") == 3   # app, apple, apple
    assert t.erase("apple") is True
    assert t.count_words_equal_to("apple") == 1      # one copy remains
    assert t.search("app") and not t.search("ap")    # 'ap' is a corridor
    print("CountingTrie OK")

class ArrayTrieNode:
    # Fixed 26-slot children: fastest hops, but every node pays for all
    # 26 references. Legal only when the alphabet is guaranteed a-z.
    __slots__ = ("children", "end")

    def __init__(self):
        self.children = [None] * 26   # index 0 = 'a' ... 25 = 'z'
        self.end = False              # does a stored word end here?


class ArrayTrie:
    # 'Implement Trie' with the array flavour + physical deletion.

    def __init__(self):
        self.root = ArrayTrieNode()

    @staticmethod
    def _idx(ch):
        return ord(ch) - 97           # map 'a'..'z' -> 0..25

    def insert(self, word):           # O(L)
        node = self.root
        for ch in word:
            i = self._idx(ch)
            if node.children[i] is None:
                node.children[i] = ArrayTrieNode()   # build missing edge
            node = node.children[i]
        node.end = True               # mark the complete word

    def _walk(self, s):
        # Follow the path spelling s; None if it breaks. O(len(s)).
        node = self.root
        for ch in s:
            node = node.children[self._idx(ch)]
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node.end    # flag required

    def starts_with(self, prefix):
        return self._walk(prefix) is not None   # path alone suffices

    def delete(self, word):
        # PHYSICAL deletion with bottom-up pruning: a node is unlinked
        # only when NO word ends at it and it has NO children left --
        # this is what protects "card" when deleting "car".
        def rec(node, depth):
            # returns True iff `node` should be unlinked by its parent
            if node is None:
                return False                     # word was never stored
            if depth == len(word):
                if not node.end:
                    return False                 # word was never stored
                node.end = False                 # unmark the word itself
            else:
                i = self._idx(word[depth])
                if rec(node.children[i], depth + 1):
                    node.children[i] = None      # prune the dead child
            # prune-able iff nothing ends here and no children remain
            return (not node.end and
                    all(c is None for c in node.children))

        rec(self.root, 0)             # root itself is never unlinked


if __name__ == "__main__":
    t = ArrayTrie()
    t.insert("car")
    t.insert("card")
    t.delete("car")                   # must NOT damage "card"
    assert not t.search("car")
    assert t.search("card") and t.starts_with("car")
    t.delete("card")                  # now the whole branch is pruned
    assert not t.starts_with("c")     # every node was reclaimed
    print("ArrayTrie OK")

