def frog_jump_k(heights, k):
    # dp[i] = minimum total energy to reach stone i starting from stone 0
    n = len(heights)
    dp = [float('inf')] * n        # inf = "not reachable yet"
    dp[0] = 0                      # base: we begin on stone 0 for free
    for i in range(1, n):
        # try every stone j we could have jumped FROM (at most k back)
        for j in range(max(0, i - k), i):
            cost = dp[j] + abs(heights[i] - heights[j])  # energy of jump j->i
            dp[i] = min(dp[i], cost)                     # keep the cheapest
    return dp[n - 1]               # O(n*k) time, O(n) space


def house_robber(nums):
    # rolling variables: prev2 = best for prefix i-2, prev1 = best for i-1
    prev2, prev1 = 0, 0
    for x in nums:
        # rob this house (x + prev2, must skip neighbor) or skip it (prev1)
        prev2, prev1 = prev1, max(prev1, prev2 + x)
    return prev1                   # O(n) time, O(1) space


def house_robber_circular(nums):
    # circle: first and last house are adjacent -> can't both be robbed
    if len(nums) == 1:
        return nums[0]
    # case A drops the last house, case B drops the first; best of the two
    return max(house_robber(nums[:-1]), house_robber(nums[1:]))

def knapsack_01(weights, values, W):
    # dp[c] = best value achievable with capacity c (items seen so far)
    dp = [0] * (W + 1)
    for wt, val in zip(weights, values):
        # DESCENDING capacity: dp[c - wt] still holds the PREVIOUS item
        # row, so this item is used at most once
        for c in range(W, wt - 1, -1):
            dp[c] = max(dp[c], dp[c - wt] + val)   # skip vs take
    return dp[W]


def unbounded_knapsack(weights, values, W):
    dp = [0] * (W + 1)
    for wt, val in zip(weights, values):
        # ASCENDING capacity: dp[c - wt] may already include this same
        # item — exactly what "unlimited copies" means
        for c in range(wt, W + 1):
            dp[c] = max(dp[c], dp[c - wt] + val)
    return dp[W]                   # Rod Cutting = this, with lengths/prices


def coin_change_min(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount      # 0 coins are needed to make amount 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1      # coin c is the LAST coin used
    return -1 if dp[amount] == INF else dp[amount]


def coin_change_count(coins, amount):
    # counts COMBINATIONS: coin loop OUTSIDE fixes the order coins are
    # introduced, so 1+2 and 2+1 collapse into one way
    dp = [1] + [0] * amount        # one way to make 0: choose nothing
    for c in coins:
        for a in range(c, amount + 1):
            dp[a] += dp[a - c]     # add ways that use at least one coin c
    return dp[amount]

def lcs(s, t):
    n, m = len(s), len(t)
    # dp[i][j] = LCS length of s[:i] and t[:j] (first i chars vs first j)
    # extra row 0 / column 0 represent the empty prefix -> base value 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i - 1] == t[j - 1]:              # last chars match
                dp[i][j] = dp[i - 1][j - 1] + 1   # extend the diagonal
            else:
                dp[i][j] = max(dp[i - 1][j],      # drop s's last char
                               dp[i][j - 1])      # drop t's last char
    return dp[n][m]                # O(n*m) time and space


def longest_palindromic_subsequence(s):
    # a subsequence common to s and reversed(s) reads the same forwards
    # and backwards -> it is a palindromic subsequence of s
    return lcs(s, s[::-1])


def distinct_subsequences(s, t):
    n, m = len(s), len(t)
    # dp[i][j] = number of ways t[:j] appears in s[:i] as a subsequence
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1               # empty t appears exactly once in any s
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j]            # ways ignoring s[i-1]
            if s[i - 1] == t[j - 1]:           # plus ways USING s[i-1]
                dp[i][j] += dp[i - 1][j - 1]   # counting -> SUM choices
    return dp[n][m]

import bisect


def lis_length_quadratic(a):
    n = len(a)
    dp = [1] * n                   # dp[i] = LIS length ending exactly at i
    for i in range(n):
        for j in range(i):
            if a[j] < a[i]:        # a[i] can extend the subseq ending at j
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp, default=0)      # the LIS may end at ANY index


def lis_length_nlogn(a):
    # tails[k] = smallest tail value of any increasing subseq of length k+1
    tails = []
    for x in a:
        pos = bisect.bisect_left(tails, x)   # first tail >= x (strict LIS)
        if pos == len(tails):
            tails.append(x)        # x extends the longest subsequence
        else:
            tails[pos] = x         # smaller tail = more room to grow later
    return len(tails)              # NOTE: tails is NOT an actual LIS


def longest_bitonic(a):
    n = len(a)
    inc = [1] * n                  # inc[i] = LIS ending at i (left to right)
    for i in range(n):
        for j in range(i):
            if a[j] < a[i]:
                inc[i] = max(inc[i], inc[j] + 1)
    dec = [1] * n                  # dec[i] = longest DECREASING starting at i
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if a[j] < a[i]:        # falling to the right of i
                dec[i] = max(dec[i], dec[j] + 1)
    # peak i is counted by both halves -> subtract the double count
    return max(inc[i] + dec[i] - 1 for i in range(n))

from collections import deque

def bfs(graph, src, n):
    # dist[v] = number of edges on the shortest src -> v path.
    dist = [-1] * n                    # -1 means "not reached yet"
    dist[src] = 0                      # source is distance 0
    q = deque([src])
    while q:
        u = q.popleft()                # O(1) — this is why we use deque
        for v in graph[u]:
            if dist[v] == -1:          # first visit = shortest layer,
                dist[v] = dist[u] + 1  #   because BFS explores by rings
                q.append(v)            # mark-at-enqueue: no duplicates
    return dist                        # unreachable nodes keep -1

def is_bipartite(graph, n):
    # Try to 2-color every component; adjacent nodes must differ.
    color = [-1] * n                   # -1 = uncolored
    for s in range(n):                 # graph may be disconnected!
        if color[s] != -1:
            continue                   # component already colored
        color[s] = 0                   # arbitrary starting color
        q = deque([s])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]    # flip: 0 <-> 1
                    q.append(v)
                elif color[v] == color[u]:
                    return False       # edge inside one color class
    return True                        #   = odd-length cycle exists

import sys
sys.setrecursionlimit(300000)          # a 500x500 grid can recurse deeply

# ---- Component counting on an adjacency list ----------------------
def count_components(graph, n):
    seen = [False] * n
    def dfs(u):
        seen[u] = True                 # mark on ENTRY, before recursing
        for v in graph[u]:
            if not seen[v]:
                dfs(v)                 # exhaust everything reachable
    comps = 0
    for s in range(n):                 # cover disconnected graphs
        if not seen[s]:
            comps += 1                 # each fresh launch = one component
            dfs(s)
    return comps

# ---- The grid IS the graph: neighbors computed on the fly ---------
DIRS = [(1, 0), (-1, 0), (0, 1), (0, -1)]      # down, up, right, left

def flood_fill(grid, r, c, new_color):
    old = grid[r][c]
    if old == new_color:
        return grid                    # guard: else infinite recursion
    R, C = len(grid), len(grid[0])
    def fill(r, c):
        grid[r][c] = new_color         # painting doubles as "visited"
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc    # candidate neighbor
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == old:
                fill(nr, nc)           # spread only into old-color cells
    fill(r, c)
    return grid

# ---- Number of Islands: same skeleton, count the launches ---------
def num_islands(grid):
    R, C = len(grid), len(grid[0])
    def sink(r, c):
        grid[r][c] = "0"               # sink land so it is never recounted
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "1":
                sink(nr, nc)
    count = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == "1":      # unvisited land found
                count += 1             # one island per DFS launch
                sink(r, c)             # erase the whole island
    return count                       # total time O(R*C): each cell twice

from collections import deque

# ---- UNDIRECTED: visited neighbor that is NOT my parent = cycle ---
def has_cycle_undirected(graph, n):
    seen = [False] * n
    def dfs(u, parent):
        seen[u] = True
        for v in graph[u]:
            if not seen[v]:
                if dfs(v, u):          # I am v's parent in the DFS tree
                    return True
            elif v != parent:          # visited, and NOT the edge I came by
                return True            # -> a second route reaches v: cycle
        return False
    for s in range(n):                 # every component must be checked
        if not seen[s] and dfs(s, -1):
            return True
    return False

# ---- Same test with BFS: carry the parent in the queue ------------
def has_cycle_undirected_bfs(graph, n):
    seen = [False] * n
    for s in range(n):
        if seen[s]:
            continue
        seen[s] = True
        q = deque([(s, -1)])           # (node, its parent)
        while q:
            u, par = q.popleft()
            for v in graph[u]:
                if not seen[v]:
                    seen[v] = True     # mark at ENQUEUE time
                    q.append((v, u))
                elif v != par:         # reached earlier via another path
                    return True
    return False

# ---- DIRECTED: 3 colors; GRAY = still on the recursion stack ------
WHITE, GRAY, BLACK = 0, 1, 2           # unvisited / active / finished

def has_cycle_directed(graph, n):
    color = [WHITE] * n
    def dfs(u):
        color[u] = GRAY                # u entered, not yet finished
        for v in graph[u]:
            if color[v] == GRAY:       # back edge into the ACTIVE path
                return True            # -> directed cycle
            if color[v] == WHITE and dfs(v):
                return True
        color[u] = BLACK               # finished: revisiting u is safe
        return False
    # launch from every white vertex (graph may be disconnected)
    return any(color[u] == WHITE and dfs(u) for u in range(n))

from collections import deque

# ---- Kahn's algorithm (BFS): peel off indegree-0 vertices ---------
def topo_kahn(graph, n):
    indeg = [0] * n
    for u in range(n):
        for v in graph[u]:
            indeg[v] += 1              # count prerequisites of v
    q = deque(u for u in range(n) if indeg[u] == 0)   # "ready" tasks
    order = []
    while q:
        u = q.popleft()
        order.append(u)                # all of u's prerequisites are done
        for v in graph[u]:
            indeg[v] -= 1              # u finished: release v a little
            if indeg[v] == 0:
                q.append(v)            # v just became ready
    if len(order) < n:
        return None                    # leftovers sit on a cycle
    return order

# ---- DFS version: reversed finishing order ------------------------
def topo_dfs(graph, n):
    seen = [False] * n
    order = []
    def dfs(u):
        seen[u] = True
        for v in graph[u]:
            if not seen[v]:
                dfs(v)
        order.append(u)                # u finishes AFTER all it points to
    for s in range(n):
        if not seen[s]:
            dfs(s)
    order.reverse()                    # reverse finish order = topo order
    return order

# ---- Shortest paths in a DAG: relax along topo order, ONE pass ----
def dag_shortest_path(wgraph, n, src):
    # wgraph[u] = [(v, w), ...]; weights may be NEGATIVE — still works.
    seen = [False] * n
    order = []
    def dfs(u):                        # topo sort of the weighted DAG
        seen[u] = True
        for v, _w in wgraph[u]:
            if not seen[v]:
                dfs(v)
        order.append(u)
    for s in range(n):
        if not seen[s]:
            dfs(s)
    order.reverse()
    INF = float("inf")
    dist = [INF] * n
    dist[src] = 0
    for u in order:                    # when u is reached, dist[u] is FINAL:
        if dist[u] == INF:             #   every path into u used earlier nodes
            continue                   # unreachable: nothing to relax
        for v, w in wgraph[u]:
            if dist[u] + w < dist[v]:  # relaxation step
                dist[v] = dist[u] + w
    return dist                        # O(V + E) total — beats Dijkstra here

import heapq

def prim_mst(wgraph, n):
    # wgraph[u] = [(v, w), ...]; undirected, both directions stored.
    in_tree = [False] * n
    pq = [(0, 0)]                      # (edge weight, node); seed node 0
    total = 0                          # sum of chosen edge weights
    picked = 0                         # how many vertices joined so far
    while pq and picked < n:
        w, u = heapq.heappop(pq)       # cheapest edge crossing the cut
        if in_tree[u]:
            continue                   # stale: u already joined the tree
        in_tree[u] = True              # u joins the tree via weight w
        total += w
        picked += 1
        for v, wv in wgraph[u]:
            if not in_tree[v]:
                heapq.heappush(pq, (wv, v))    # new candidate crossing edge
    if picked != n:
        return None                    # graph not connected: no spanning tree
    return total                       # O(E log V) with the lazy heap

