from collections import defaultdict, deque


class Graph:
    """Adjacency-list graph over vertices 0..n-1. Space O(V + E)."""

    def __init__(self, n, directed=False):
        self.n = n                          # number of vertices
        self.directed = directed
        self.adj = defaultdict(list)        # u -> list of neighbors

    def add_edge(self, u, v):
        # O(1): append to the adjacency list(s).
        self.adj[u].append(v)               # edge u -> v
        if not self.directed:
            self.adj[v].append(u)           # undirected: mirror the edge

    def bfs(self, src):
        # Layer-by-layer traversal. O(V + E).
        seen = [False] * self.n
        seen[src] = True                    # mark at ENQUEUE, not dequeue
        order = []
        q = deque([src])
        while q:
            u = q.popleft()                 # O(1) thanks to deque
            order.append(u)
            for v in self.adj[u]:
                if not seen[v]:
                    seen[v] = True          # prevents queue duplicates
                    q.append(v)
        return order

    def dfs_recursive(self, src):
        # Preorder DFS from src. O(V + E).
        seen = [False] * self.n
        order = []
        def go(u):
            seen[u] = True                  # mark on entry
            order.append(u)                 # preorder: record when entered
            for v in self.adj[u]:
                if not seen[v]:
                    go(v)                   # dive before trying siblings
        go(src)
        return order

    def dfs_iterative(self, src):
        # Explicit-stack DFS: immune to Python's recursion limit.
        seen = [False] * self.n
        order = []
        stack = [src]
        while stack:
            u = stack.pop()                 # LIFO pop -> depth-first order
            if seen[u]:
                continue                    # u may be on the stack twice
            seen[u] = True
            order.append(u)
            for v in reversed(self.adj[u]): # reversed so the FIRST listed
                if not seen[v]:             #   neighbor is popped first
                    stack.append(v)
        return order

    def topo_sort_kahn(self):
        # BFS topo sort; returns None when a cycle exists. O(V + E).
        indeg = [0] * self.n
        for u in range(self.n):
            for v in self.adj[u]:
                indeg[v] += 1               # count prerequisites of v
        q = deque(u for u in range(self.n) if indeg[u] == 0)
        order = []
        while q:
            u = q.popleft()
            order.append(u)                 # all prerequisites of u done
            for v in self.adj[u]:
                indeg[v] -= 1               # u no longer blocks v
                if indeg[v] == 0:
                    q.append(v)             # v just became ready
        # fewer than n output => leftovers are stuck on a cycle
        return order if len(order) == self.n else None

    def topo_sort_dfs(self):
        # Reverse of DFS finish times. Assumes the graph is a DAG.
        seen = [False] * self.n
        out = []
        def dfs(u):
            seen[u] = True
            for v in self.adj[u]:
                if not seen[v]:
                    dfs(v)
            out.append(u)                   # appended only when FINISHED
        for s in range(self.n):             # cover disconnected pieces
            if not seen[s]:
                dfs(s)
        out.reverse()                       # reversed finish order = topo
        return out


if __name__ == "__main__":
    g = Graph(6, directed=True)
    for u, v in [(5, 2), (5, 0), (4, 0), (4, 1), (2, 3), (3, 1)]:
        g.add_edge(u, v)                    # small dependency DAG
    print(g.topo_sort_kahn())               # [4, 5, 2, 0, 3, 1]
    print(g.topo_sort_dfs())                # another valid topo order
    print(g.bfs(5))                         # e.g. [5, 2, 0, 3, 1]
    print(g.dfs_iterative(5))               # matches dfs_recursive(5)

