class TrieNode:
    __slots__ = ("zero", "one")        # child for bit 0 / child for bit 1
    def __init__(self):
        self.zero = None
        self.one = None

class XorTrie:
    def __init__(self, bits=32):
        self.root = TrieNode()
        self.bits = bits               # fixed width; walk HIGH bit first

    def insert(self, x):
        node = self.root
        for i in range(self.bits - 1, -1, -1):
            b = x >> i & 1             # bit i of x
            if b:
                if node.one is None:
                    node.one = TrieNode()      # create the path lazily
                node = node.one
            else:
                if node.zero is None:
                    node.zero = TrieNode()
                node = node.zero       # O(bits) per insert

    def max_xor_with(self, x):
        # Greedy: at each level try the branch holding the OPPOSITE
        # bit of x — that forces a 1 into the highest possible position.
        node = self.root
        best = 0
        for i in range(self.bits - 1, -1, -1):
            b = x >> i & 1
            want = node.one if b == 0 else node.zero   # opposite branch
            if want is not None:
                best |= 1 << i         # secured a 1 at bit i
                node = want
            else:
                node = node.one if b else node.zero    # forced same bit
        return best                    # O(bits) per query

