    # xor(l..r) = P[r] ^ P[l-1]  ->  best XOR pair among prefixes.
    trie = XorTrie()
    trie.insert(0)                     # P[-1] = 0: the empty prefix
    best = 0
    p = 0
    for x in nums:
        p ^= x                         # running prefix xor P[r]
        best = max(best, trie.max_xor_with(p))
        trie.insert(p)                 # future prefixes may pair with p
    return best

