# A complete min-heap on a plain Python list — what heapq does under the
# hood. Index math (0-based): parent (i-1)//2, children 2i+1 and 2i+2.

class MinHeap:
    def __init__(self, items=None):
        self.a = list(items) if items else []
        if self.a:
            self._heapify()          # O(N) bottom-up build, not N pushes

    def __len__(self):
        return len(self.a)

    def peek(self):
        # O(1): the invariant guarantees the minimum sits at the root.
        if not self.a:
            raise IndexError('peek from empty heap')
        return self.a[0]

    def push(self, x):
        # O(log N): append as the new last leaf (keeps the tree complete),
        # then bubble it up while it is smaller than its parent.
        self.a.append(x)
        self._sift_up(len(self.a) - 1)

    def pop(self):
        # O(log N): the root is the answer; fill the hole with the LAST
        # leaf (completeness preserved), then sink it to its proper place.
        if not self.a:
            raise IndexError('pop from empty heap')
        top = self.a[0]
        last = self.a.pop()          # remove the final leaf
        if self.a:                   # heap non-empty: last leaf becomes root
            self.a[0] = last
            self._sift_down(0, len(self.a))
        return top

    def _sift_up(self, i):
        a = self.a
        while i > 0:
            parent = (i - 1) // 2    # index arithmetic instead of pointers
            if a[i] < a[parent]:     # child smaller -> invariant broken
                a[i], a[parent] = a[parent], a[i]   # swap upward
                i = parent           # continue from the parent's slot
            else:
                break                # parent <= child: order restored

    def _sift_down(self, i, n):
        a = self.a
        while True:
            left, right = 2 * i + 1, 2 * i + 2
            smallest = i
            # Pick the smaller of the two children — sinking must swap with
            # the SMALLER child or the other child would break the invariant.
            if left < n and a[left] < a[smallest]:
                smallest = left
            if right < n and a[right] < a[smallest]:
                smallest = right
            if smallest == i:        # both children >= node: done sinking
                break
            a[i], a[smallest] = a[smallest], a[i]
            i = smallest             # follow the node down the tree

    def _heapify(self):
        n = len(self.a)
        # Leaves are already 1-element heaps; fix internal nodes bottom-up.
        # Total cost is O(N): most nodes are near the bottom with tiny
        # sift distances (sum of heights converges to N).
        for i in range(n // 2 - 1, -1, -1):
            self._sift_down(i, n)


def heapsort(items):
    # O(N log N), and shows the heap doing real work: build once in O(N),
    # then pop the minimum N times.
    h = MinHeap(items)
    return [h.pop() for _ in range(len(h))]


if __name__ == '__main__':
    print(heapsort([5, 1, 8, 3, 2, 9, 4]))   # [1, 2, 3, 4, 5, 8, 9]

