def three_sum(nums):
    nums.sort()                     # sortedness is the licence for pointer moves
    res = []
    n = len(nums)
    for i in range(n - 2):          # nums[i] is the fixed ANCHOR of the triple
        if nums[i] > 0:
            break                   # smallest element positive -> no zero triple
        if i > 0 and nums[i] == nums[i - 1]:
            continue                # same anchor value again -> would duplicate
        l, r = i + 1, n - 1         # converging pair on the sorted suffix
        target = -nums[i]           # need nums[l] + nums[r] == -nums[i]
        while l < r:
            s = nums[l] + nums[r]
            if s < target:
                l += 1              # too small: any r' <= r keeps it small -> drop l
            elif s > target:
                r -= 1              # too big: any l' >= l keeps it big -> drop r
            else:
                res.append([nums[i], nums[l], nums[r]])   # found one triple
                l += 1
                r -= 1
                while l < r and nums[l] == nums[l - 1]:
                    l += 1          # hop over equal values -> no duplicate pairs
                while l < r and nums[r] == nums[r + 1]:
                    r -= 1          # symmetric skip on the right side
    return res                      # O(N^2) time after O(N log N) sort, O(1) extra

def max_consecutive_ones(nums):
    best = streak = 0
    for x in nums:
        if x == 1:
            streak += 1             # extend the current run of 1s
            if streak > best:
                best = streak       # record a new record IMMEDIATELY
        else:
            streak = 0              # a 0 kills the run: reset, never rescan
    return best                     # O(N) time, O(1) space, one pass
    # The same "extend or reset" skeleton, given a budget of k flips,
    # becomes the sliding window of "Max Consecutive Ones III".

