# A tiny decorator that prints every call and return, indented by the
# current stack depth -- it turns the invisible call stack into text.
# Run it once on factorial (a chain) and once on fib (a branching tree)
# and the complexity difference becomes something you can SEE.

import functools

def trace(fn):
    # depth is stored on the wrapper so all nested calls share one counter
    @functools.wraps(fn)
    def wrapper(*args):
        pad = '|  ' * wrapper.depth               # one bar per live stack frame
        print(f"{pad}-> {fn.__name__}{args}")     # frame pushed
        wrapper.depth += 1                        # we are now one level deeper
        result = fn(*args)                        # the real recursive work
        wrapper.depth -= 1                        # this frame is about to pop
        print(f"{pad}<- {fn.__name__}{args} returns {result}")
        return result
    wrapper.depth = 0                             # module-load initial depth
    return wrapper

@trace
def factorial(n):
    # BASE CASE: 0! is defined as 1 -- stops the descent
    if n == 0:
        return 1
    # RECURSIVE CASE: trust factorial(n-1), then combine with one multiply
    return n * factorial(n - 1)

@trace
def fib(n):
    # two base cases cover the two smallest inputs
    if n <= 1:
        return n
    # TWO recursive calls -> the tree doubles each level -> O(2^n) growth
    return fib(n - 1) + fib(n - 2)

if __name__ == '__main__':
    print('--- factorial(4): a straight chain, max depth 5 ---')
    factorial(4)
    print('--- fib(4): a tree; note fib(2) is recomputed twice ---')
    fib(4)      # the repeated subtrees you see here are what memoization removes

