def word_break(s, words):
    # Can s be segmented into dictionary words? (Word Break, memoized)
    word_set = set(words)              # O(1) average membership tests
    memo = {}                          # start index -> can s[start:] be segmented?
    def solve(start):
        if start == len(s):            # empty suffix: vacuously segmentable
            return True
        if start in memo:              # been here via a different prefix cut
            return memo[start]         # O(1) instead of re-searching the subtree
        for end in range(start + 1, len(s) + 1):
            # CHOOSE the prefix s[start:end]; recurse only if it is a real word
            if s[start:end] in word_set and solve(end):
                memo[start] = True     # cache the success
                return True            # no undo needed: nothing was mutated
        memo[start] = False            # cache the FAILURE -- this line is the
        return False                   # difference between O(2^n) and O(n^2)
    return solve(0)

print(word_break("applepenapple", ["apple", "pen"]))        # True
print(word_break("catsandog", ["cats", "dog", "sand", "and", "cat"]))  # False

