# Two Sudoku solvers sharing one skeleton:
#   solve_basic : validity by scanning row/col/box  -- the interview baseline
#   solve_fast  : 27 sets (9 rows, 9 cols, 9 boxes) -- O(1) checks, same search
# Boards are 9x9 lists of single-char strings; '.' marks an empty cell.

def solve_basic(board):
    def valid(r, c, ch):
        br, bc = 3 * (r // 3), 3 * (c // 3)    # 3x3 box top-left corner
        for k in range(9):
            if board[r][k] == ch or board[k][c] == ch:
                return False                   # row or column clash
            if board[br + k // 3][bc + k % 3] == ch:
                return False                   # box clash
        return True
    def fill():
        for r in range(9):
            for c in range(9):
                if board[r][c] != '.':
                    continue                   # decided cell -> keep scanning
                for ch in '123456789':
                    if valid(r, c, ch):
                        board[r][c] = ch       # choose
                        if fill():             # explore
                            return True        # solved below -> freeze everything
                        board[r][c] = '.'      # un-choose
                return False                   # no digit fits -> backtrack
        return True                            # no empty cell -> solved
    return fill()

def solve_fast(board):
    rows = [set() for _ in range(9)]           # digits used in each row
    cols = [set() for _ in range(9)]           # digits used in each column
    boxes = [set() for _ in range(9)]          # digits used in each 3x3 box
    empties = []                               # coordinates still to fill
    for r in range(9):
        for c in range(9):
            ch = board[r][c]
            if ch == '.':
                empties.append((r, c))         # remember the blanks
            else:
                b = 3 * (r // 3) + c // 3      # box index 0..8
                rows[r].add(ch); cols[c].add(ch); boxes[b].add(ch)
    def fill(i):
        if i == len(empties):                  # all blanks filled
            return True
        r, c = empties[i]
        b = 3 * (r // 3) + c // 3
        for ch in '123456789':
            # three O(1) lookups replace the 27-cell scan
            if ch in rows[r] or ch in cols[c] or ch in boxes[b]:
                continue
            board[r][c] = ch                   # choose: write + 3 set adds
            rows[r].add(ch); cols[c].add(ch); boxes[b].add(ch)
            if fill(i + 1):                    # explore the next blank
                return True
            board[r][c] = '.'                  # un-choose: erase + 3 discards
            rows[r].discard(ch); cols[c].discard(ch); boxes[b].discard(ch)
        return False                           # dead end -> caller retries
    return fill(0)

if __name__ == '__main__':
    puzzle = [list(row) for row in [
        "53..7....", "6..195...", ".98....6.",
        "8...6...3", "4..8.3..1", "7...2...6",
        ".6....28.", "...419..5", "....8..79"]]
    solve_fast(puzzle)                          # solve in place
    for row in puzzle:                          # print the completed grid
        print(''.join(row))

