def is_balanced(s):
    # Map each closer to the opener it must match.
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []                            # unmatched openers, most recent on top
    for ch in s:
        if ch in '([{':
            stack.append(ch)              # a new context opens
        elif ch in pairs:
            # A closer must match the MOST RECENT open context (LIFO).
            if not stack or stack[-1] != pairs[ch]:
                return False              # nothing open, or wrong type
            stack.pop()                   # matched -> that context is closed
        # (other characters would be ignored here)
    # Balanced only if every opener found its closer.
    return not stack                      # empty stack == fully matched

from collections import deque

class StackUsingQueue:
    # ONE queue. We make push O(N) so that pop/top become O(1).
    def __init__(self):
        self.q = deque()                  # front of q == top of stack

    def push(self, x):
        self.q.append(x)                  # x enters at the tail
        # Rotate everyone older behind x, so x reaches the FRONT.
        for _ in range(len(self.q) - 1):
            self.q.append(self.q.popleft())   # move front to back

    def pop(self):
        return self.q.popleft()           # front is the newest -> LIFO order

    def top(self):
        return self.q[0]                  # peek without removing

    def empty(self):
        return not self.q                 # deque truthiness: empty == falsy

def sort_stack(stack):
    # Sorts in place, smallest at the bottom, using ONLY stack ops.
    # The call stack silently acts as the second stack.
    if stack:
        top = stack.pop()                 # hold one element in this frame
        sort_stack(stack)                 # sort everything underneath
        insert_sorted(stack, top)         # weave the held element back in
    return stack


def insert_sorted(stack, x):
    # Pre-condition: stack is sorted, LARGEST value on top.
    if not stack or stack[-1] <= x:
        stack.append(x)                   # x is >= the top -> belongs on top
    else:
        bigger = stack.pop()              # lift one bigger element out
        insert_sorted(stack, x)           # sink x deeper into the stack
        stack.append(bigger)              # restore the lifted element

from collections import OrderedDict

class LRUCache:
    # OrderedDict = hash map + doubly linked list of keys in one object:
    # exactly the two structures the LRU design calls for.
    def __init__(self, capacity):
        self.cap = capacity
        self.od = OrderedDict()           # oldest key at the left end

    def get(self, key):
        if key not in self.od:
            return -1                     # miss
        self.od.move_to_end(key)          # refresh: key is now most recent
        return self.od[key]

    def put(self, key, value):
        if key in self.od:
            self.od.move_to_end(key)      # updating counts as a use too
        self.od[key] = value              # insert or overwrite the value
        if len(self.od) > self.cap:
            self.od.popitem(last=False)   # evict least-recently used (left end)

