class ArrayStack:
    # Fixed-capacity stack backed by a pre-allocated array.
    # We manage the 'top' index ourselves -- this is what
    # "Implement Stack Using Array" wants, not list.append.

    def __init__(self, capacity):
        self.capacity = capacity          # maximum number of elements
        self.data = [None] * capacity     # pre-allocated storage slots
        self.top = -1                     # index of top element; -1 == empty

    def is_empty(self):
        return self.top == -1             # no slot in use

    def is_full(self):
        return self.top == self.capacity - 1   # last slot in use

    def size(self):
        return self.top + 1               # slots 0..top are occupied

    def push(self, x):
        if self.is_full():
            raise OverflowError("push onto full stack")   # overflow guard
        self.top += 1                     # claim the next free slot...
        self.data[self.top] = x           # ...and write the value there

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")      # underflow guard
        x = self.data[self.top]           # read the top value
        self.data[self.top] = None        # optional: drop the reference (GC)
        self.top -= 1                     # shrink the stack by one
        return x

    def peek(self):
        if self.is_empty():
            raise IndexError("peek at empty stack")       # underflow guard
        return self.data[self.top]        # read WITHOUT removing


