from collections import deque

def sliding_window_max(nums, k):
    # O(N) maximum of every length-k window via a monotonic deque.
    dq = deque()                  # indices; nums values DECREASE front->back
    out = []
    for i, x in enumerate(nums):
        # (1) Expire the front if it slid out of the window [i-k+1, i].
        if dq and dq[0] <= i - k:
            dq.popleft()          # oldest index no longer in the window
        # (2) x kills every back element that is <= x: those are
        #     older AND not larger, so they can never be a future max.
        while dq and nums[dq[-1]] <= x:
            dq.pop()              # dominated element leaves forever
        dq.append(i)              # x itself may be a future maximum
        # (3) Once the first window is complete, the front IS the max.
        if i >= k - 1:
            out.append(nums[dq[0]])
    return out                    # each index enters/leaves dq once: O(N)

class MinStack:
    # Every level stores (value, min of the stack up to that level),
    # so the current minimum always sits on top -- O(1) to read,
    # and popping automatically 'rolls back' to the older minimum.

    def __init__(self):
        self.st = []                      # list of (value, running_min)

    def push(self, x):
        if self.st:
            cur_min = self.st[-1][1]      # minimum BEFORE this push
        else:
            cur_min = x                   # first element defines the min
        self.st.append((x, min(x, cur_min)))   # min INCLUDING x rides along

    def pop(self):
        return self.st.pop()[0]           # paired min disappears with it

    def top(self):
        return self.st[-1][0]             # plain top value

    def get_min(self):
        return self.st[-1][1]             # the answer travels with the data

from collections import deque

def oranges_rotting(grid):
    # Multi-source BFS: minutes until every reachable fresh orange rots.
    rows, cols = len(grid), len(grid[0])
    q = deque()
    fresh = 0
    # Seed the queue with EVERY rotten orange at minute 0.
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                q.append((r, c, 0))       # (row, col, minute it rotted)
            elif grid[r][c] == 1:
                fresh += 1                # count survivors to verify later
    minutes = 0
    while q:
        r, c, t = q.popleft()             # FIFO -> minutes never decrease
        minutes = max(minutes, t)         # last level reached = total time
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc       # the four grid neighbours
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                grid[nr][nc] = 2          # mark visited ON ENQUEUE
                fresh -= 1                # one fewer fresh orange
                q.append((nr, nc, t + 1)) # rots exactly one minute later
    # Any fresh orange left is unreachable -> the rot never completes.
    return -1 if fresh else minutes

