class MinStack:
    # Variant 1: (value, running_min) pair per level. Simple, safe,
    # works for any orderable payload. Space: 2 numbers per element.

    def __init__(self):
        self.st = []                      # list of (value, min_so_far)

    def push(self, x):
        if self.st:
            m = self.st[-1][1]            # minimum before this push
        else:
            m = x                         # first element defines it
        self.st.append((x, x if x < m else m))   # carry min WITH the data

    def pop(self):
        return self.st.pop()[0]           # its paired min vanishes too

    def top(self):
        return self.st[-1][0]

    def get_min(self):
        return self.st[-1][1]             # O(1) read, always current


class MinStackO1:
    # Variant 2: O(1) EXTRA space. One number per level + one 'mn' var.
    # Invariant: a stored entry e is either the real value (e >= mn at
    # push time) or an ENCODED marker e = 2*x - old_mn pushed when x
    # became the new minimum. Since x < old_mn, e < x = mn, so markers
    # are recognizable: they are strictly below the current minimum.
    # (Safe in Python: ints never overflow. In C++/Java, 2*x can.)

    def __init__(self):
        self.st = []                      # raw or encoded numbers
        self.mn = None                    # current minimum, None == empty

    def push(self, x):
        if not self.st:
            self.st.append(x)             # first element: store as-is
            self.mn = x                   # and it IS the minimum
        elif x < self.mn:
            self.st.append(2 * x - self.mn)   # encode: remembers old_mn
            self.mn = x                   # x is the new minimum
        else:
            self.st.append(x)             # ordinary value, store raw

    def pop(self):
        e = self.st.pop()                 # raw value OR encoded marker
        if e < self.mn:                   # marker detected...
            real, self.mn = self.mn, 2 * self.mn - e   # decode old min
            return real                   # true popped value was mn
        return e                          # plain value, mn unchanged

    def top(self):
        e = self.st[-1]
        return self.mn if e < self.mn else e   # markers hide mn on top

    def get_min(self):
        return self.mn                    # single variable, O(1)


