def reverse_words(s):
    # split() with no args collapses runs of spaces AND trims ends,
    # so "  hello   world  " -> ["hello", "world"].
    return " ".join(reversed(s.split()))


def reverse_words_in_place(chars):
    # chars: list of characters (lists mutate; strings cannot).
    def rev(lo, hi):
        # two-pointer swap; everything outside [lo,hi] is final
        while lo < hi:
            chars[lo], chars[hi] = chars[hi], chars[lo]
            lo += 1
            hi -= 1

    n = len(chars)
    rev(0, n - 1)                 # "cat dog" -> "god tac"
    start = 0
    for i in range(n + 1):
        # a word ends at a space or at the end of the buffer
        if i == n or chars[i] == " ":
            rev(start, i - 1)     # repair one word: "god" -> "dog"
            start = i + 1         # next word starts after the space
    return chars


def longest_common_prefix(strs):
    # Vertical scan: column by column across every word.
    if not strs:
        return ""
    shortest = min(strs, key=len)         # answer can't beat this
    for i, ch in enumerate(shortest):
        for other in strs:
            if other[i] != ch:            # first disagreement
                return shortest[:i]       # prefix = columns before i
    return shortest                       # all columns agreed

def my_atoi(s):
    i, n = 0, len(s)
    # STATE 1: skip leading spaces (only spaces, per the spec).
    while i < n and s[i] == " ":
        i += 1
    # STATE 2: at most one sign character.
    sign = 1
    if i < n and s[i] in "+-":
        sign = -1 if s[i] == "-" else 1
        i += 1
    # STATE 3: accumulate digits; first non-digit ends the number.
    num = 0
    while i < n and s[i].isdigit():
        num = num * 10 + (ord(s[i]) - ord("0"))   # shift left base 10
        i += 1
    num *= sign
    # STATE 4: clamp — Python ints never overflow, so WE must.
    INT_MIN, INT_MAX = -2**31, 2**31 - 1
    return max(INT_MIN, min(INT_MAX, num))


def roman_to_int(s):
    # Values only — subtractive pairs fall out of the rule below.
    val = {"I": 1, "V": 5, "X": 10, "L": 50,
           "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, ch in enumerate(s):
        # smaller symbol BEFORE a bigger one is subtracted
        if i + 1 < len(s) and val[ch] < val[s[i + 1]]:
            total -= val[ch]      # the I of "IV" contributes -1
        else:
            total += val[ch]      # ordinary additive symbol
    return total

def longest_palindromic_substring(s):
    if not s:
        return ""
    best_lo, best_hi = 0, 0           # inclusive bounds of best answer

    def expand(lo, hi):
        # grow while both ends agree; invariant: s[lo..hi] palindrome
        while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        # loop overshoots one step each side -> step back in
        return lo + 1, hi - 1

    for c in range(len(s)):
        # odd-length: single-character center at c
        lo, hi = expand(c, c)
        if hi - lo > best_hi - best_lo:
            best_lo, best_hi = lo, hi
        # even-length: center in the GAP between c and c+1
        lo, hi = expand(c, c + 1)
        if hi - lo > best_hi - best_lo:
            best_lo, best_hi = lo, hi
    return s[best_lo:best_hi + 1]     # one final O(n) slice

def rabin_karp(text, pat):
    n, m = len(text), len(pat)
    if m == 0:
        return list(range(n + 1))   # empty pattern matches everywhere
    if m > n:
        return []                   # cannot fit
    B, M = 256, 1_000_000_007       # base >= alphabet; large prime mod
    high = pow(B, m - 1, M)         # weight of the OUTGOING character
    ph = th = 0
    for i in range(m):
        # Horner's rule: hash = hash*B + next_char  (mod M)
        ph = (ph * B + ord(pat[i])) % M
        th = (th * B + ord(text[i])) % M
    hits = []
    for i in range(n - m + 1):
        # equal hashes -> PROBABLE match; verify to kill collisions
        if ph == th and text[i:i + m] == pat:
            hits.append(i)
        if i + m < n:
            # roll: drop text[i], shift, append text[i+m]
            th = (th - ord(text[i]) * high) % M
            th = (th * B + ord(text[i + m])) % M
    return hits

def build_lps(p):
    # lps[i] = longest proper prefix of p[:i+1] that is also a suffix
    m = len(p)
    lps = [0] * m                  # lps[0] = 0: 'proper' excludes whole
    k = 0                          # length of border being extended
    for i in range(1, m):
        # shrink the border until p[i] can extend it (or it dies)
        while k > 0 and p[i] != p[k]:
            k = lps[k - 1]         # fall back to next-smaller border
        if p[i] == p[k]:
            k += 1                 # border grew by one character
        lps[i] = k
    return lps


def kmp_search(text, pat):
    # every start index of pat inside text, in O(n + m)
    if not pat:
        return list(range(len(text) + 1))
    lps = build_lps(pat)
    hits, j = [], 0                # j = pattern chars matched so far
    for i, ch in enumerate(text):  # i NEVER moves backwards
        while j > 0 and ch != pat[j]:
            j = lps[j - 1]         # reuse matched prefix knowledge
        if ch == pat[j]:
            j += 1
        if j == len(pat):          # full match ending at i
            hits.append(i - j + 1)
            j = lps[j - 1]         # continue: allows overlapping hits
    return hits

def z_function(s):
    # z[i] = length of longest common prefix of s and s[i:]
    n = len(s)
    z = [0] * n
    if n == 0:
        return z
    z[0] = n                       # whole string matches itself
    l, r = 0, 0                    # rightmost prefix-match window [l, r)
    for i in range(1, n):
        if i < r:
            # mirror trick: i behaves like i-l, capped by window edge
            z[i] = min(r - i, z[i - l])
        # extend past the window with real comparisons
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]     # new rightmost window
    return z


def z_search(text, pat):
    # all occurrences of pat in text via ONE z pass: O(n + m)
    if not pat:
        return list(range(len(text) + 1))
    combined = pat + "#" + text    # '#' must appear in neither input
    z = z_function(combined)
    m = len(pat)
    # z[i] == m at combined index i  ->  text index i - m - 1
    return [i - m - 1 for i in range(m + 1, len(z)) if z[i] >= m]

