# ==================================================================
# Two tiny building blocks that string interviews lean on constantly.
# 1) StringBuilder: WHY "list buffer + one join" beats += in a loop.
#    Each s += t copies all of s (immutable!), so N appends cost
#    1 + 2 + ... + N = O(N^2). A list buffer appends references in
#    amortized O(1) and joins once at the end: O(N) total.
# 2) CharCounter: fixed-size frequency table for a known alphabet —
#    the O(1)-per-update engine behind anagram and window problems.
# ==================================================================

class StringBuilder:
    # Mutable accumulator that freezes into a string in O(total).

    def __init__(self):
        self._parts = []           # fragments, joined lazily at the end

    def append(self, fragment):
        # amortized O(1): stores a reference, copies nothing yet
        self._parts.append(fragment)
        return self                # enables chaining: sb.append(a).append(b)

    def build(self):
        # ONE allocation + one copy pass over all fragments: O(total)
        return "".join(self._parts)


class CharCounter:
    # Frequency table over lowercase a-z using a plain 26-slot list.

    def __init__(self, s=""):
        self.freq = [0] * 26       # slot 0 = 'a' ... slot 25 = 'z'
        for ch in s:
            self.add(ch)           # count initial contents

    def add(self, ch):
        # ord math replaces a hash lookup: O(1), tiny constant
        self.freq[ord(ch) - ord("a")] += 1

    def remove(self, ch):
        # used when a sliding window slides a char out
        self.freq[ord(ch) - ord("a")] -= 1

    def __eq__(self, other):
        # equal counters <=> all 26 counts agree <=> same multiset
        return self.freq == other.freq


if __name__ == "__main__":
    sb = StringBuilder()
    for i in range(5):
        sb.append(str(i))          # collected without any copying
    assert sb.build() == "01234"   # single join at the end
    # anagrams have identical frequency tables
    assert CharCounter("listen") == CharCounter("silent")
    print("Toolkit OK")

