def build_lps(p):
    # prefix function from Part-I: lps[i] = longest proper border
    lps = [0] * len(p)
    k = 0                          # border length being extended
    for i in range(1, len(p)):
        while k > 0 and p[i] != p[k]:
            k = lps[k - 1]         # shrink to next smaller border
        if p[i] == p[k]:
            k += 1
        lps[i] = k
    return lps


def longest_palindromic_prefix_len(s):
    # border of s + '#' + rev(s)  ==  palindromic prefix of s
    if not s:
        return 0
    combined = s + "#" + s[::-1]   # '#' must not occur inside s
    return build_lps(combined)[-1] # last value = the answer, O(n)


def min_chars_for_palindrome(s):
    # keep the palindromic prefix; mirror everything after it
    return len(s) - longest_palindromic_prefix_len(s)


def shortest_palindrome(s):
    # the actual string: reversed tail prepended to s
    k = longest_palindromic_prefix_len(s)
    return s[k:][::-1] + s         # e.g. "abcd" -> "dcb" + "abcd"

from collections import Counter

def is_anagram_sort(a, b):
    # canonical form = sorted character sequence; O(n log n)
    return sorted(a) == sorted(b)

def is_anagram_counter(a, b):
    # canonical form = frequency map; O(n) time, O(k) space
    if len(a) != len(b):
        return False               # cheap O(1) gate first
    return Counter(a) == Counter(b)

def is_anagram_array(a, b):
    # fixed 26 slots when input is guaranteed lowercase a-z
    if len(a) != len(b):
        return False
    freq = [0] * 26
    for x, y in zip(a, b):         # one pass over both strings
        freq[ord(x) - 97] += 1     # char from a: +1
        freq[ord(y) - 97] -= 1     # char from b: -1
    # anagram <=> every count cancelled back to zero
    return all(v == 0 for v in freq)

