# ==================================================================
# strstr(haystack, needle): index of the FIRST occurrence, or -1.
# Two builds: the naive scanner (write this first) and the KMP
# version (offer it when asked for worst-case O(n + m)).
# ==================================================================

def strstr_naive(haystack, needle):
    # check every alignment; O(n*m) worst case, O(1) extra space
    n, m = len(haystack), len(needle)
    if m == 0:
        return 0                   # convention: empty needle -> 0
    for i in range(n - m + 1):     # last viable start is n - m
        j = 0
        # march j while characters agree at this alignment
        while j < m and haystack[i + j] == needle[j]:
            j += 1
        if j == m:
            return i               # matched all m characters
    return -1                      # every alignment failed


def strstr_kmp(haystack, needle):
    # first occurrence in O(n + m) using the prefix function
    if not needle:
        return 0
    # build lps for the needle (border lengths — see Part-I)
    lps = [0] * len(needle)
    k = 0
    for i in range(1, len(needle)):
        while k > 0 and needle[i] != needle[k]:
            k = lps[k - 1]         # fall back to a smaller border
        if needle[i] == needle[k]:
            k += 1
        lps[i] = k
    j = 0                          # needle chars matched so far
    for i, ch in enumerate(haystack):
        while j > 0 and ch != needle[j]:
            j = lps[j - 1]         # slide the needle, i stays put
        if ch == needle[j]:
            j += 1
        if j == len(needle):
            return i - j + 1       # FIRST full match: report and stop
    return -1


if __name__ == "__main__":
    # both versions must agree on every case
    for f in (strstr_naive, strstr_kmp):
        assert f("sadbutsad", "sad") == 0
        assert f("leetcode", "leeto") == -1
        assert f("mississippi", "issip") == 4
        assert f("abc", "") == 0            # empty-needle convention
    print("strstr OK")
